    features["zcr"] = extract_zero_crossing_rate(audio_path)
    features["spectral_centroid"] = extract_spectral_centroid(audio_path)
    features["mfcc"] = extract_mfcc(audio_path)
    features["num_onsets"] = extract_num_onsets(audio_path)
    features["tempo"] = extract_tempo(audio_path)
    return features

